function predictTheWinner(nums) {
  const n = nums.length;
  const diff = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let i = 0; i < n; i++) {
    diff[i][i] = nums[i];
  }

  for (let length = 2; length <= n; length++) {
    for (let left = 0; left + length - 1 < n; left++) {
      const right = left + length - 1;
      const takeLeft = nums[left] - diff[left + 1][right];
      const takeRight = nums[right] - diff[left][right - 1];
      diff[left][right] = Math.max(takeLeft, takeRight);
    }
  }

  return diff[0][n - 1] >= 0;
}

