function predictTheWinner(nums) {
  // Plain minimax on (first score - second score): Player 1 maximises it, Player 2 minimises it.
  const play = (lo, hi, firstToMove) => {
    if (lo > hi) return 0;
    const sign = firstToMove ? 1 : -1;
    const a = sign * nums[lo] + play(lo + 1, hi, !firstToMove);
    const b = sign * nums[hi] + play(lo, hi - 1, !firstToMove);
    return firstToMove ? Math.max(a, b) : Math.min(a, b);
  };
  return play(0, nums.length - 1, true) >= 0;
}

