function generate(rand, size) {
  if (size === 'large') {
    const n = 17 + Math.floor(rand() * 4);
    return [Array.from({ length: n }, () => Math.floor(rand() * 10000001))];
  }
  const n = 1 + Math.floor(rand() * 9);
  const span = rand() < 0.3 ? 3 : 30;
  return [Array.from({ length: n }, () => Math.floor(rand() * (span + 1)))];
